function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();
  for (let i = 1; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W/2, H/2, 50 + 20*Math.sin(t) + i*10, 0, 2*Math.PI);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(W/2 + (50 + 20*Math.sin(t) + i*5)*Math.cos(i+t), 
            H/2 + (50 + 20*Math.sin(t) + i*5)*Math.sin(i+t), 
            5, 0, 2*Math.PI);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(W/2 + (50 + 20*Math.sin(t) + i*5)*Math.cos(i+t), 
            H/2 + (50 + 20*Math.sin(t) + i*5)*Math.sin(i+t), 
            5, 0, 2*Math.PI);
    ctx.stroke();
  }
  ctx.restore();
}
